    async def send_bulk_same_message(
        self,
        *,
        instance_name: str,
        recipients: Sequence[str],
        text: str,
        pacing: BulkPacing | None = None,
        idempotency_key: str | None = None,
        time_limit: float | None = None,
    ) -> Sent[BulkJob]:
        """Starts a bulk job: one text for many recipients.

        The core stores the job and sends its messages in the background. The job survives a restart
        of the core.

        Args:
            instance_name: The instance that sends the messages.
            recipients: 1 or more recipients, in the format of `to` of `send_plain_text`. Each
                recipient can be in the list only once.
            text: The text of the message, sent unchanged. It cannot be empty or only spaces.
            pacing: The pacing of the job. `None` means the default of the provider.
            idempotency_key: The key of this job: 1 to 255 printable ASCII characters, with no
                space. Make it with `new_idempotency_key` and store it before the call. Use a new
                key for each job. Use the same key only to repeat the same call. Calyx keeps a key
                for 24 hours. In that time, a second call with the same key does not send again.
                Without it, the SDK makes a new key. All callers of one instance share its keys.
            time_limit: The time limit of the call, in seconds. Without it, the `time_limit` of the
                SDK client applies, or 120 seconds when it has none.

        Returns:
            Sent[BulkJob]: `data` is the answer, and `idempotency_key` is the key that the call
                used. A bulk job: many messages that one instance sends in the background, with
                delays between them.

        Raises:
            CalyxError: The call failed. Read `retry` of the error to know what to do. Compare
                `code` with `CoreCode` and `ClientCode`. No connection, or a connection that breaks,
                gives `CoreCode.UNAVAILABLE`. When `retry` is `RetryAdvice.RETRY_NOW`, call again
                with the same arguments and the `idempotency_key` of the error. When it is
                `RetryAdvice.RETRY_LATER`, do the same, but first wait for `retry_after` seconds or
                more. If it is 0, choose the time to wait. Calyx forgets a key after 24 hours, so do
                not call again after that time. A cancelled call raises no `CalyxError`, and a key
                that the SDK made is lost. A cancelled call with no stored key cannot be repeated
                safely.
        """
        return await self._send(
            SEND_BULK_SAME_MESSAGE,
            lambda key: convert.send_bulk_same_message_request(
                instance_name=instance_name,
                recipients=recipients,
                text=text,
                pacing=pacing,
                idempotency_key=key,
            ),
            convert.read_bulk_job,
            idempotency_key=idempotency_key,
            time_limit=time_limit,
        )

